class GitHubHttpTransport:
    """Reusable GitHub HTTP client using GraphQL for PRs and REST for protection.

    The caller must pass a resolved bearer token. This class deliberately raises
    ``GitHubApiError`` so node-specific adapters can translate failures into
    their own transport error contracts.
    """

    _PR_PAGE_SIZE = 100
    _DECISIVE_REVIEW_STATES = ("APPROVED", "CHANGES_REQUESTED")

    def __init__(self, token: str) -> None:
        if not token:
            raise RuntimeError(
                "GitHub token must not be empty. Resolve it via the contract "
                "api_key_ref before constructing GitHubHttpTransport."
            )
        self._token = token

    def _graphql(self, query: str, variables: dict[str, object]) -> dict[str, Any]:
        return graphql(query, variables, token=self._token)

    def _rest_get(self, path: str) -> dict[str, Any] | None:
        try:
            return rest_json("GET", path, token=self._token)
        except GitHubApiError as exc:
            if exc.status_code == 404:
                return None
            raise

    def fetch_open_prs(self, repo: str) -> list[dict[str, Any]]:
        """Fetch open PRs via GitHub GraphQL API."""
        owner, name = split_repo(repo)
        all_prs: list[dict[str, Any]] = []
        cursor: str | None = None

        while True:
            variables: dict[str, object] = {"owner": owner, "name": name}
            if cursor:
                variables["after"] = cursor

            data = self._graphql(_PR_GRAPHQL_QUERY, variables)
            repo_data = data.get("repository")
            if not repo_data:
                break

            pr_conn = repo_data.get("pullRequests", {})
            nodes = pr_conn.get("nodes", [])
            for node in nodes:
                label_nodes = (node.get("labels") or {}).get("nodes", [])
                node["labels"] = [
                    {"name": ln["name"]} for ln in label_nodes if ln and "name" in ln
                ]

                commit_nodes = (node.get("statusCheckRollup") or {}).get("nodes") or []
                rollup_nodes: list[dict[str, Any]] = []
                if commit_nodes:
                    rollup_nodes = (
                        (commit_nodes[0].get("commit") or {}).get(
                            "statusCheckRollup", {}
                        )
                        or {}
                    ).get("contexts", {}).get("nodes", []) or []
                node["statusCheckRollup"] = _normalize_open_pr_rollup(rollup_nodes)

                raw_threads = (node.get("reviewThreads") or {}).get("nodes") or []
                node["reviewThreads"] = _normalize_review_threads(raw_threads)

                raw_files = (node.get("files") or {}).get("nodes") or []
                node["files"] = [
                    {"path": file_node["path"]}
                    for file_node in raw_files
                    if isinstance(file_node, dict) and file_node.get("path")
                ]
                all_prs.append(node)

            page_info = pr_conn.get("pageInfo", {})
            if not page_info.get("hasNextPage"):
                break
            cursor = page_info.get("endCursor")

        return all_prs

    def fetch_branch_protection(self, repo: str) -> int | None:
        """Fetch required_approving_review_count via REST API."""
        data = self._rest_get(f"/repos/{repo}/branches/main/protection")
        if data is None:
            return None
        reviews = data.get("required_pull_request_reviews")
        if not isinstance(reviews, dict):
            return None
        raw = reviews.get("required_approving_review_count")
        if isinstance(raw, int):
            return raw
        return None

    def fetch_combined_status(self, repo: str, sha: str) -> str:
        """Fetch the combined commit status for ``sha``, degrading to pending.

        An empty sha is pending by definition and never issues a request; any
        failed read degrades to the neutral ``pending`` value.
        """
        if not sha:
            return "pending"
        try:
            data = rest_json(
                "GET", f"/repos/{repo}/commits/{sha}/status", token=self._token
            )
        except GitHubApiError:
            return "pending"
        if not isinstance(data, dict):
            return "pending"
        state = data.get("state")
        return state if isinstance(state, str) else "pending"

    def fetch_review_states(self, repo: str, number: int) -> list[str]:
        """Fetch the latest decisive review state per reviewer.

        COMMENTED (and missing/unknown states) never decide; the most recent
        decisive review wins. A failed read degrades to no states.
        """
        try:
            reviews = rest_json_array(
                "GET", f"/repos/{repo}/pulls/{number}/reviews", token=self._token
            )
        except GitHubApiError:
            return []

        latest: dict[str, str] = {}
        for review in reviews or []:
            if not isinstance(review, dict):
                continue
            user = review.get("user")
            login = user.get("login") if isinstance(user, dict) else None
            state = review.get("state")
            if not login or state not in self._DECISIVE_REVIEW_STATES:
                continue
            latest[login] = state
        return list(latest.values())

    def fetch_open_prs_for_triage(self, repo: str) -> list[dict[str, Any]]:
        """Fetch open PRs via REST, augmented with status and review states.

        A failed PR list is an error; the per-PR reads (combined status,
        review states) degrade to their neutral values.
        """
        triage_prs: list[dict[str, Any]] = []
        page = 1
        while True:
            batch = rest_json_array(
                "GET",
                f"/repos/{repo}/pulls?state=open"
                f"&per_page={self._PR_PAGE_SIZE}&page={page}",
                token=self._token,
            )
            for pr in batch or []:
                if not isinstance(pr, dict):
                    continue
                head = pr.get("head")
                sha = head.get("sha") if isinstance(head, dict) else None
                pr["combined_status"] = self.fetch_combined_status(repo, sha or "")
                pr["review_states"] = self.fetch_review_states(
                    repo, pr.get("number", 0)
                )
                triage_prs.append(pr)
            if len(batch or []) < self._PR_PAGE_SIZE:
                break
            page += 1
        return triage_prs
